-- CAREEROS P3-T08: cohorts (phase plan D8). The CREATE TABLE and index statements are generated by drizzle-kit; the
-- ON DELETE SET NULL column lists, row-level security and grants are written by hand, following P4-T01. The three
-- indexes on session, resume and application serve the Org Admin analytics queries (plan in the pull request). Runs as
-- the migration (owner) role. Down migration: down.sql in this folder.
CREATE TABLE "cohort" (
	"id" text PRIMARY KEY,
	"organization_id" text NOT NULL,
	"name" text NOT NULL,
	"description" text,
	"starts_on" date,
	"ends_on" date,
	"archived_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "cohort_organization_id_id_unique" UNIQUE("organization_id","id"),
	CONSTRAINT "cohort_name_check" CHECK (char_length(btrim("name")) between 1 and 100),
	CONSTRAINT "cohort_description_check" CHECK ("description" is null or char_length("description") <= 1000),
	CONSTRAINT "cohort_dates_check" CHECK ("starts_on" is null or "ends_on" is null or "ends_on" >= "starts_on")
);
--> statement-breakpoint
ALTER TABLE "invitation" ADD COLUMN "cohort_id" text;--> statement-breakpoint
CREATE INDEX "application_org_created_idx" ON "application" ("organization_id","created_at");--> statement-breakpoint
CREATE INDEX "session_active_org_user_idx" ON "session" ("active_organization_id","user_id","updated_at");--> statement-breakpoint
CREATE INDEX "resume_org_created_idx" ON "resume" ("organization_id","created_at");--> statement-breakpoint
CREATE UNIQUE INDEX "cohort_organization_name_key" ON "cohort" ("organization_id",lower("name"));--> statement-breakpoint
CREATE INDEX "member_org_cohort_idx" ON "member" ("organization_id","cohort_id");--> statement-breakpoint
ALTER TABLE "cohort" ADD CONSTRAINT "cohort_organization_id_organization_id_fkey" FOREIGN KEY ("organization_id") REFERENCES "organization"("id") ON DELETE CASCADE;--> statement-breakpoint
-- The column existed without a key and nothing could write it (Better Auth declares it input: false), so no row can
-- name a cohort that is valid; clear any stray value so the keys below can be added.
UPDATE "member" SET "cohort_id" = NULL WHERE "cohort_id" IS NOT NULL;--> statement-breakpoint
-- Both keys are composite onto (organization_id, id), so a cohort of another organization cannot be named. SET NULL
-- lists the cohort column only (PostgreSQL 15+): deleting a cohort never clears the tenant column. No CASCADE.
ALTER TABLE "invitation" ADD CONSTRAINT "invitation_org_cohort_fkey" FOREIGN KEY ("organization_id","cohort_id") REFERENCES "cohort"("organization_id","id") ON DELETE SET NULL ("cohort_id");--> statement-breakpoint
ALTER TABLE "member" ADD CONSTRAINT "member_org_cohort_fkey" FOREIGN KEY ("organization_id","cohort_id") REFERENCES "cohort"("organization_id","id") ON DELETE SET NULL ("cohort_id");--> statement-breakpoint
-- Row-level security (D4), exactly as P1-T04 and P4-T01: FORCE applies the policy to the table owner too, so only
-- owner_access lets the owner role (migrations, definer functions) see every organization. careeros_app only matches
-- its own organization; an unset setting is NULL and matches nothing (fail closed).
ALTER TABLE "cohort" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "cohort" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
DROP POLICY IF EXISTS "tenant_isolation" ON "cohort";--> statement-breakpoint
CREATE POLICY "tenant_isolation" ON "cohort"
	USING ("organization_id" = current_setting('app.current_org_id', true))
	WITH CHECK ("organization_id" = current_setting('app.current_org_id', true));--> statement-breakpoint
DROP POLICY IF EXISTS "owner_access" ON "cohort";--> statement-breakpoint
CREATE POLICY "owner_access" ON "cohort" TO CURRENT_USER USING (true) WITH CHECK (true);--> statement-breakpoint
-- Table privileges for the app role. The bootstrap's default privileges already cover tables the owner creates; this
-- grant makes the migration correct on a database where the roles were created differently. Idempotent.
DO $$ BEGIN
	IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'careeros_app') THEN
		GRANT SELECT, INSERT, UPDATE, DELETE ON "cohort" TO careeros_app;
	END IF;
END $$;
